// intent: Verify that getting bool from a json_view boolean succeeds and returns true.
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>

int main() {
    try {
        auto doc = nlohmann::json_document::parse("true");
        auto view = doc.root();
        bool val = view.get<bool>();
        std::cout << "SUCCESS: " << (val ? "true" : "false") << std::endl;
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << std::endl;
    }
}
